      ctx.lineWidth = rng.range(1, 2.5);
      ctx.beginPath();
      const y0 = rng() * 256;
      ctx.moveTo(0, y0);
      for (let x = 0; x <= 256; x += 16) ctx.lineTo(x, y0 + Math.sin(x * 0.05 + i) * 5);
      ctx.stroke();
