  for (let i = 0; i < 40; i++) {
    const x = rng.range(layout.beach.x0 + 12, layout.beach.x1 - 5);
    const z = rng.range(layout.beach.z0 + 24, layout.beach.z1 - 24);
    if (rng.chance(0.55)) {
      const col = rng.pick([
