  // Market stalls in the parks.
  for (const block of layout.blocks) {
    if (block.kind !== 'park') continue;
    for (let i = 0; i < 5; i++) {
      const x = block.x0 + 10 + rng.range(0, block.x1 - block.x0 - 20);
      const z = block.z0 + 10 + rng.range(0, block.z1 - block.z0 - 20);
      const col = rng.pick([
        [0.9, 0.35, 0.3],
        [0.95, 0.8, 0.35],
        [0.25, 0.7, 0.65],
