    const z = layout.roadsZ[0] + 25 + rng.range(0, layout.roadsZ[layout.roadsZ.length - 1] - layout.roadsZ[0] - 50);
    const x = rx + (rng.chance(0.5) ? 1 : -1) * (layout.driveHalf + 4.2);
